CREATE TABLE public.crypto_wallets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset text NOT NULL CHECK (asset IN ('USDT','BTC','ETH')), network text NOT NULL, address text NOT NULL, min_deposit numeric(18,2) NOT NULL DEFAULT 1 CHECK (min_deposit > 0), max_deposit numeric(18,2) NOT NULL DEFAULT 1000000 CHECK (max_deposit >= min_deposit), deposit_fee numeric(18,2) NOT NULL DEFAULT 0 CHECK (deposit_fee >= 0), withdrawal_fee numeric(18,2) NOT NULL DEFAULT 0 CHECK (withdrawal_fee >= 0), active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT crypto_wallet_unique UNIQUE (asset,network));
GRANT SELECT, INSERT, UPDATE ON public.crypto_wallets TO authenticated; GRANT ALL ON public.crypto_wallets TO service_role;
ALTER TABLE public.crypto_wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY crypto_wallets_read ON public.crypto_wallets FOR SELECT TO authenticated USING ((active AND deleted_at IS NULL) OR public.is_staff(auth.uid()));
CREATE POLICY crypto_wallets_create ON public.crypto_wallets FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE POLICY crypto_wallets_edit ON public.crypto_wallets FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE TRIGGER crypto_wallets_touch BEFORE UPDATE ON public.crypto_wallets FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
ALTER TABLE public.deposits ADD COLUMN wallet_id uuid REFERENCES public.crypto_wallets(id), ADD COLUMN wallet_address text;
CREATE OR REPLACE FUNCTION public.validate_deposit_wallet() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _wallet public.crypto_wallets%ROWTYPE; BEGIN IF NEW.user_id IS DISTINCT FROM auth.uid() OR NEW.wallet_id IS NULL THEN RAISE EXCEPTION 'Choose an available deposit wallet'; END IF; SELECT * INTO _wallet FROM public.crypto_wallets WHERE id=NEW.wallet_id AND active AND deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Deposit wallet unavailable'; END IF; IF NEW.amount < _wallet.min_deposit OR NEW.amount > _wallet.max_deposit THEN RAISE EXCEPTION 'Amount outside wallet deposit limits'; END IF; NEW.asset := _wallet.asset; NEW.network := _wallet.network; NEW.wallet_address := _wallet.address; RETURN NEW; END $$;
CREATE TRIGGER deposits_validate_wallet BEFORE INSERT ON public.deposits FOR EACH ROW EXECUTE FUNCTION public.validate_deposit_wallet();
CREATE OR REPLACE FUNCTION public.audit_crypto_wallet_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'wallet_created' ELSE 'wallet_updated' END,'crypto_wallet',NEW.id,jsonb_build_object('asset',NEW.asset,'network',NEW.network,'active',NEW.active)); RETURN NEW; END $$;
CREATE TRIGGER crypto_wallet_audit AFTER INSERT OR UPDATE ON public.crypto_wallets FOR EACH ROW EXECUTE FUNCTION public.audit_crypto_wallet_change();
REVOKE ALL ON FUNCTION public.validate_deposit_wallet(), public.audit_crypto_wallet_change() FROM PUBLIC, anon, authenticated;